function longestSpreadOne(nums: number[]): number {
  let best = 0;
  for (const x of nums) {
    let low = 0, high = 0;
    for (const y of nums) {
      if (y === x) low++;
      else if (y === x + 1) high++;
    }
    if (high > 0) best = Math.max(best, low + high);
  }
  return best;
}

