class Solution:
    def longestSpreadOne(self, nums: List[int]) -> int:
        best = 0
        for x in nums:
            low = sum(1 for y in nums if y == x)
            high = sum(1 for y in nums if y == x + 1)
            if high:
                best = max(best, low + high)
        return best

